%[text] %[text:anchor:T_90DC58E9] # 
%[text] %[text:anchor:T_DD1A2D9E] # Read me
%[text] This mlx is thought to be executed **section by section**: the user can modify small pieces in order to express his/her preferences.
%[text] User must not modify the name of the variables!
%[text] User must click on Run Section to see the results of his/her modifications.
%[text] 
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] 
%%
%[text] 
%[text] %[text:anchor:H_3086C821] ## Import image
%[text] This section must be run only once!!!

import iftiread.*
import niftiinfo.*

% Read the NIfTI file
data = niftiread("sub2_t1_2_t2.nii");
% Get information about the NIfTI file
info = niftiinfo("sub2_t1_2_t2.nii");
numOfGreyLevels = 2 ^ info.BitsPerPixel;

left_ventricle_volume = zeros(256,256,30);
right_ventricle_volume = zeros(256,256,30);

voxel_dim = info.PixelDimensions(1,1) * info.PixelDimensions(1,2) * info.PixelDimensions(1,3);
dimension = info.SpaceUnits;

%%
%[text] %[text:anchor:H_093134AA] ## 
%[text] %[text:anchor:H_99D408E1] ## Slice selection
%[text] Choose the slice you want to work with by modifying the number

slice_number = 16 ;

%[text] \-------------------------------------

img = data(:, :, slice_number);
% Convert values to double for normalization
img = im2double(img);
% Normalize values
image = ( img - min(img(:)) )./( max(img(:)) - min(img(:)) );

figure; %[output:0f19923d]
imshow(image); %[output:0f19923d]
title([ 'Original image: slice ', num2str(slice_number) ] ); %[output:0f19923d]

figure; %[output:7dfef1da]
histogram(image, 'NumBins', numOfGreyLevels); %[output:7dfef1da]
xlabel('Intensity'); %[output:7dfef1da]
ylabel('Frequency'); %[output:7dfef1da]
title('Intensity Histogram'); %[output:7dfef1da]

%%
%[text] %[text:anchor:H_E130E337] ## 
%[text] %[text:anchor:H_84C67803] ## Noise simulation
%[text] If you want to simulate noise on your image, select the typee of noise and its intensity, then Run Section

gaussian_mean = 0.1 ;
img_w_noise = imnoise(image,'gaussian', gaussian_mean);

% salt_pepper_density = 0.2 ;
% img_w_noise = imnoise(image,'salt & pepper', salt_pepper_density);

%[text] \-------------------------------------

figure %[output:15887d25]
subplot(1,2,1), imshow(image), title('Original Image') %[output:15887d25]
subplot(1,2,2), imshow(img_w_noise), title('Image with noise') %[output:15887d25]

%%
%[text] %[text:anchor:H_869F43AD] ## 
%[text] Run this sectiono if you want to use the new image from now on

image = img_w_noise;

%%
%[text] %[text:anchor:H_0BE60503] ## 
%[text] %[text:anchor:H_C6EF70E5] ## Noise removal
%[text] You can see the effects of noise removal on your image
%[text] Next, you'll be able to choose which image to keep (the original or one of the noise-removal versions)

% avg filters
avg_filt_3 = 1/9.*ones(3,3);
avg_filt_5 = 1/25.*ones(5,5);
img_3avg  = imfilter(image, avg_filt_3, 'conv');
img_5avg  = imfilter(image, avg_filt_5, 'conv');

% median filters
img_3med  = medfilt2(image, [3 3]);
img_5med  = medfilt2(image, [5 5]);

% vector for user selection
img_noise_removing = zeros(size(image,1), size(image,2), 5);
img_noise_removing(:,:,1) = image;
img_noise_removing(:,:,2) = img_3avg;
img_noise_removing(:,:,3) = img_5avg;
img_noise_removing(:,:,4) = img_3med;
img_noise_removing(:,:,5) = img_5med;


% show results to the user
figure %[output:773d7b5c]
imshow(image,[]), title('Original Image: #1') %[output:773d7b5c]

figure %[output:491a5086]
imshow(img_3avg, []), title('avg filt 3: #2') %[output:491a5086]

figure %[output:01ea4565]
imshow(img_5avg, []), title('avg filt 5: #3') %[output:01ea4565]

figure %[output:07034e8b]
imshow(img_3med, []), title('median 3x3: #4') %[output:07034e8b]

figure %[output:32c80869]
imshow(img_5med, []), title('median 5x5: #5') %[output:32c80869]

%%
%[text] %[text:anchor:H_A83795FE] ## 
%[text] If you used Noise Removal, select the number corresponding to the image you want to use from now on

selected_index = 5 ;

%[text] \-------------------------------------

image = img_noise_removing(:,:,selected_index);

%%
%[text] %[text:anchor:H_762CDB1C] ## 
%[text] %[text:anchor:H_4B7E71BC] ## Personalized normalization
%[text] Here you can set the parameters for a new normalization

norm_min = 0 ;
norm_max = 0.8 ;

%[text] \-------------------------------------

new_norm = ( image - norm_min )./( norm_max - norm_min );

figure %[output:7ff590f4]
subplot(121), imshow(image); title('Current Image'); %[output:7ff590f4]
subplot(122), imshow(new_norm); title('Image with new norm'); %[output:7ff590f4]

%%
%[text] Run this Section if you want to use the new image from now on

image = new_norm;

%%
%[text] 
%[text] %[text:anchor:H_C18D0C46] ## Gamma function
%[text] Select gamma and the range in which you want to apply the gamma transformation, then Run this Section to see the resulting image compared with the original one

gamma = 1.8 ;
LOW_out = 0 ;
HIGH_out = 1 ;
LOW_in = 0;
HIGH_in = 1;

%[text] \-------------------------------------

gamma_image = imadjust(image,[LOW_in HIGH_in],[LOW_out HIGH_out], gamma);

figure %[output:30d3a90f]
subplot(121), imshow(image); title('Current Image'); %[output:30d3a90f]
subplot(122), imshow(gamma_image); title('Image after gamma'); %[output:30d3a90f]

%%
%[text] %[text:anchor:H_27790336] ## 
%[text] Run this section if you want to use the new image from now on

image = gamma_image;

%%
%[text] %[text:anchor:H_B6B5935A] ## 
%[text] %[text:anchor:H_F70D8809] ## Edge detection
%[text] Choose the mask you want to use by uncommenting the corresponding line (leave the others commented)
%[text] If you want, you can create a new mask

mask = [0 1 0; 0 0 0; 0 -1 0];
% mask = [1 2 1; 0 0 0; -2 -1 -1];
% mask = [ 1  2  3  2  1; 0  1  2  1  2; 0  0  0  0  0; 0 -1 -2 -2  1; -1 -2 -3 -2 -1];
% mask = [ build ; your ; mask ];

%[text] \-------------------------------------

hy = mask ;
hx = mask';

% derivative computation in the two directions
Gx = imfilter(image, hx, 'conv');
Gy = imfilter(image, hy, 'conv');
img_modified_gradient = abs(Gx)+abs(Gy);

% absolute values
figure %[output:2d02e4bf]
subplot(131), imshow(abs(Gx), [], 'InitialMagnification', 'fit'), title('Gx module') %[output:2d02e4bf]
subplot(132), imshow(abs(Gy), [], 'InitialMagnification', 'fit'), title('Gy module') %[output:2d02e4bf]
subplot(133), imshow(img_modified_gradient, [], 'InitialMagnification', 'fit'), title('Sum') %[output:2d02e4bf]

% norm sum
norm_sum = ( img_modified_gradient - min(img_modified_gradient(:)) )./( max(img_modified_gradient(:)) - min(img_modified_gradient(:)) );
figure %[output:4a08a885]
imshow(norm_sum); %[output:4a08a885]
title('Norm sum'); %[output:4a08a885]

% several gradient thresholds
% threshold = linspace(0, max(image(:)), 11);
threshold = linspace(0, max(norm_sum(:)), 11);

img_edge = zeros(size(img_modified_gradient,1), size(img_modified_gradient,2), 11);

for i=2:length(threshold) %[output:group:9bb09502]
    figure %[output:56781eaa] %[output:4d721e9d] %[output:64017c66] %[output:1e85dee2] %[output:12a6f09b] %[output:55771625] %[output:1865b1bf] %[output:5ac65fdd] %[output:0142d746] %[output:9776f1b8]
    img_to_show = imbinarize(img_modified_gradient, threshold(i));
    imshow(img_to_show); %[output:56781eaa] %[output:4d721e9d] %[output:64017c66] %[output:1e85dee2] %[output:12a6f09b] %[output:55771625] %[output:1865b1bf] %[output:5ac65fdd] %[output:0142d746] %[output:9776f1b8]
    img_edge(:,:,i) = img_to_show;
    title( strcat('#', num2str(i-1), ' thr = ', num2str(threshold(i))) );
end %[output:group:9bb09502]

%%
%[text] %[text:anchor:H_9B92BD18] ## 
%[text] %[text:anchor:H_1C9FE112] ## Area computation
%[text] Image selection:
%[text] Among the images you see, input the one you want to be used for the computation of the ventricle area (must be between 1 and 10)
%[text] If you want to calculate the area using the image instead of the borders-images, set 0

selected_image_index = 4 ;

%[text] Then, double click inside the region of which you want to know the area
%[text] \-------------------------------------

img_edge(:,:,1) = ~image;           % useful with some t2 images
selected_contoured_img = img_edge(:,:,selected_image_index+1);
imshow(selected_contoured_img); %[output:70f1e534]
BW = bwselect(~selected_contoured_img,4); %[output:33d27ad4]
BW2 = imfill(BW,"holes");
imshow(BW2); %[output:7a106c01]
%Area_BW = length(find(BW))
Area = length(find(BW2)) %[output:5bb131e8]

%%
%[text] %[text:anchor:H_F9B77DCC] ## 
%[text] %[text:anchor:H_88AD1C2E] ## 3D image update
%[text] Indicate here which ventricle you selected (by commenting the other one)

selected_ventricle = 'right';
%selected_ventricle = 'left ';

%[text] then Run Section
%[text] \-------------------------------------

if selected_ventricle == 'right'
    right_ventricle_volume(:,:,slice_number) = right_ventricle_volume(:,:,slice_number) + BW2;
else
    left_ventricle_volume(:,:,slice_number)  = left_ventricle_volume(:,:,slice_number)  + BW2;
end

%%
%[text] %[text:anchor:H_BE7AE406] ## 
%[text] %[text:anchor:H_16CD7A82] ## Volume computation

total_white_voxels_right_ventricle = length(find(right_ventricle_volume(:,:,:)));
right_volume = total_white_voxels_right_ventricle * voxel_dim;
fprintf('Volume of right ventricle is %f Cubed %s' , right_volume, dimension ); %[output:651f81e6]

total_white_voxels_left_ventricle = length(find(left_ventricle_volume(:,:,:)));
left_volume = total_white_voxels_left_ventricle * voxel_dim;
fprintf('Volume of left ventricle is %f Cubed %s' , left_volume, dimension ); %[output:78bb2db3]

%%
%[text] 
%[text] %[text:anchor:H_FEF54DA9] ## Slice 16 segmentation performance
%%

BW_manual_segm = imbinarize(imread("BW_manual_segmentation.jpg"));
BW_computed_segm = BW2 ;
% BW_computed_segm = imbinarize(imread("BW_computed_segmentation.jpg"));
% uncomment next line to test with slice 16 found by you
%BW_computed_segm = right_ventricle_volume(:,:,16) + left_ventricle_volume(:,:,16);

figure %[output:67bc7c07]
subplot(1,2,1), imshow(BW_manual_segm), title("Manual segmentation"); %[output:67bc7c07]
subplot(1,2,2), imshow(BW_computed_segm), title("Computed segmentation"); %[output:67bc7c07]

TP = 0;
TN = 0;
FP = 0;
FN = 0;

for i=1:256
    for j=1:256
        if BW_manual_segm(i,j) == 1
            if BW_computed_segm(i,j) == 1
                TP = TP + 1;
            else
                FN = FN + 1;
            end
        else
            if BW_computed_segm(i,j) == 1
                FP = FP + 1;
            else
                TN = TN + 1;
            end
        end
    end
end

sensitivity = TP / (TP+FN) %[output:2e7fba8f]
specificity = TN / (TN+FP) %[output:4b852188]
dice_coeff  = 2*TP / ( 2*TP + FP + FN) %[output:75a586da]

TP = 0;
TN = 0;
FP = 0;
FN = 0;


% same copmutation but with pixels from (50,50) to (200,200)
for i=100:157
    for j=86:156
        if BW_manual_segm(i,j) == 1
            if BW_computed_segm(i,j) == 1
                TP = TP + 1;
            else
                FN = FN + 1;
            end
        else
            if BW_computed_segm(i,j) == 1
                FP = FP + 1;
            else
                TN = TN + 1;
            end
        end
    end
end

sensitivity_on_restricted_region = TP / (TP+FN) %[output:2064ae12]
specificity_on_restricted_region = TN / (TN+FP) %[output:4740c1e8]
dice_coeff_on_restricted_region  = 2*TP / ( 2*TP + FP + FN) %[output:75bb9476]




